/* CreativeHub Design System */

/* ===== CSS Variables ===== */
:root {
  /* Brand Colors */
  --color-primary: #F02D00;
  --color-primary-dark: #D12600;
  --color-primary-light: #FF4D2E;
  --color-foreground: #171717;
  --color-white: #FFFFFF;
  --color-background: #FFFFFF;
  --color-surface: #F8F8F8;
  --color-border: #E5E5E5;

  /* Accent - Vibrant Teal */
  --color-accent: #00B4A0;
  --color-accent-dark: #009688;
  --color-accent-light: #26C6DA;

  /* Text Colors */
  --color-text-primary: #171717;
  --color-text-secondary: #666666;
  --color-text-muted: #999999;
  --color-text-inverse: #FFFFFF;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 2rem;
  --font-size-4xl: 2.5rem;
  --font-size-5xl: 3rem;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.07);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 20px 25px rgba(0, 0, 0, 0.15);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;

  /* Container */
  --container-max: 1280px;
  --container-padding: 1.5rem;
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--color-text-primary);
  background-color: var(--color-background);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
}

h1 { font-size: var(--font-size-4xl); }
h2 { font-size: var(--font-size-3xl); }
h3 { font-size: var(--font-size-2xl); }
h4 { font-size: var(--font-size-xl); }
h5 { font-size: var(--font-size-lg); }
h6 { font-size: var(--font-size-base); }

/* ===== Layout ===== */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-padding);
}

.section {
  padding: var(--spacing-3xl) 0;
}

/* ===== Header ===== */
.header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
}

.logo {
  font-size: var(--font-size-2xl);
  font-weight: 800;
  color: var(--color-foreground);
}

.logo span {
  color: var(--color-primary);
}

.nav-main {
  display: flex;
  align-items: center;
  gap: var(--spacing-xl);
}

.nav-link {
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--color-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
}

.search-btn {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  background: var(--color-surface);
  border-radius: var(--radius-full);
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
  transition: all var(--transition-fast);
}

.search-btn:hover {
  background: var(--color-border);
  color: var(--color-text-primary);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-sm);
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--color-foreground);
  color: var(--color-white);
}

.btn-secondary:hover {
  background: #333;
}

.btn-outline {
  border: 2px solid var(--color-border);
  color: var(--color-text-primary);
}

.btn-outline:hover {
  border-color: var(--color-foreground);
  background: var(--color-foreground);
  color: var(--color-white);
}

.btn-ghost {
  color: var(--color-text-secondary);
}

.btn-ghost:hover {
  color: var(--color-text-primary);
  background: var(--color-surface);
}

.mobile-menu-btn {
  display: none;
  padding: var(--spacing-sm);
}

/* ===== Promo Banner ===== */
.promo-banner {
  background: linear-gradient(135deg, var(--color-primary) 0%, #FF6B35 100%);
  color: var(--color-white);
  padding: var(--spacing-sm) var(--spacing-md);
  text-align: center;
  position: relative;
}

.promo-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.promo-text {
  font-weight: 600;
}

.promo-countdown {
  display: flex;
  gap: var(--spacing-sm);
}

.countdown-item {
  background: rgba(255, 255, 255, 0.2);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: var(--radius-sm);
  font-weight: 700;
  min-width: 40px;
  text-align: center;
}

.countdown-separator {
  animation: blink 1s infinite;
}

@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

.promo-close {
  position: absolute;
  right: var(--spacing-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-white);
  opacity: 0.8;
  padding: var(--spacing-xs);
}

.promo-close:hover {
  opacity: 1;
}

/* ===== Hero Carousel ===== */
.hero-section {
  padding: var(--spacing-3xl) 0;
  background: var(--color-surface);
}

.hero-carousel {
  position: relative;
  overflow: hidden;
}

.hero-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.hero-slide {
  min-width: 100%;
  display: flex;
  align-items: center;
  gap: var(--spacing-3xl);
  padding: var(--spacing-xl);
}

.hero-content {
  flex: 1;
}

.hero-badge {
  display: inline-block;
  background: var(--color-accent);
  color: var(--color-white);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-md);
}

.hero-title {
  font-size: var(--font-size-4xl);
  margin-bottom: var(--spacing-md);
  color: var(--color-foreground);
}

.hero-description {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
  max-width: 500px;
}

.hero-meta {
  display: flex;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-lg);
  color: var(--color-text-muted);
  font-size: var(--font-size-sm);
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
}

.hero-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-lg);
}

.price-current {
  font-size: var(--font-size-3xl);
  font-weight: 800;
  color: var(--color-primary);
}

.price-original {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.hero-image {
  flex: 1;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
}

.hero-image img {
  width: 100%;
  height: 350px;
  object-fit: cover;
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.carousel-arrow {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-foreground);
  transition: all var(--transition-fast);
}

.carousel-arrow:hover {
  background: var(--color-foreground);
  color: var(--color-white);
  transform: scale(1.05);
}

.carousel-dots {
  display: flex;
  gap: var(--spacing-sm);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  background: var(--color-primary);
  width: 30px;
  border-radius: var(--radius-full);
}

/* ===== Course Card ===== */
.course-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  border: 1px solid var(--color-border);
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.course-card-image {
  position: relative;
  overflow: hidden;
  aspect-ratio: 16/10;
}

.course-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.course-card:hover .course-card-image img {
  transform: scale(1.05);
}

.course-badge {
  position: absolute;
  top: var(--spacing-sm);
  left: var(--spacing-sm);
  background: var(--color-primary);
  color: var(--color-white);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
  font-weight: 700;
  text-transform: uppercase;
}

.course-badge.bestseller {
  background: #FFB800;
  color: var(--color-foreground);
}

.course-badge.free {
  background: var(--color-accent);
}

.course-card-content {
  padding: var(--spacing-md);
}

.course-card-category {
  font-size: var(--font-size-xs);
  color: var(--color-accent);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-xs);
}

.course-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-card-instructor {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-sm);
}

.course-card-stats {
  display: flex;
  gap: var(--spacing-md);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-sm);
}

.course-card-stats span {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
}

.course-card-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  margin-bottom: var(--spacing-md);
}

.rating-stars {
  color: #FFB800;
}

.rating-count {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}

.course-card-price {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-sm);
}

.course-card-price .current {
  font-size: var(--font-size-lg);
  font-weight: 800;
  color: var(--color-primary);
}

.course-card-price .original {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  text-decoration: line-through;
}

/* ===== Course Grid ===== */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-xl);
}

/* ===== Course Carousel ===== */
.course-carousel {
  position: relative;
  overflow: hidden;
}

.course-carousel-track {
  display: flex;
  gap: var(--spacing-xl);
  transition: transform var(--transition-slow);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding: var(--spacing-sm);
}

.course-carousel-track::-webkit-scrollbar {
  display: none;
}

.course-carousel .carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
}

.course-carousel .carousel-arrow.prev {
  left: -24px;
}

.course-carousel .carousel-arrow.next {
  right: -24px;
}

/* ===== Section Headers ===== */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-xl);
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.section-title {
  font-size: var(--font-size-2xl);
  color: var(--color-foreground);
}

.section-link {
  color: var(--color-primary);
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
}

.section-link:hover {
  text-decoration: underline;
}

/* ===== Value Props ===== */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-xl);
}

.value-prop {
  display: flex;
  gap: var(--spacing-md);
}

.value-prop-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--color-primary) 0%, #FF6B35 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  flex-shrink: 0;
}

.value-prop-content h4 {
  font-size: var(--font-size-base);
  margin-bottom: var(--spacing-xs);
}

.value-prop-content p {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
}

/* ===== Footer ===== */
.footer {
  background: var(--color-foreground);
  color: var(--color-white);
  padding: var(--spacing-3xl) 0 var(--spacing-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-2xl);
  margin-bottom: var(--spacing-2xl);
}

.footer-section h4 {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--spacing-lg);
  color: var(--color-white);
}

.footer-section ul {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.footer-section a {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.7);
  transition: color var(--transition-fast);
}

.footer-section a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--spacing-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}

.footer-logo {
  font-size: var(--font-size-xl);
  font-weight: 800;
}

.footer-logo span {
  color: var(--color-primary);
}

.footer-legal {
  display: flex;
  gap: var(--spacing-lg);
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.5);
}

.footer-legal a {
  color: inherit;
}

.footer-legal a:hover {
  color: var(--color-white);
}

.footer-apps {
  display: flex;
  gap: var(--spacing-md);
}

.footer-app-btn {
  background: rgba(255, 255, 255, 0.1);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  transition: background var(--transition-fast);
}

.footer-app-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.footer-accordion-header h4 {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.footer-accordion-icon {
  transition: transform var(--transition-fast);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.footer-accordion.active .footer-accordion-icon {
  transform: rotate(180deg);
}

.footer-accordion.active .footer-accordion-content {
  max-height: 500px;
}

.footer-accordion-content ul {
  padding: var(--spacing-md) 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.footer-accordion-content a {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.7);
}

/* ===== Courses Page ===== */
.page-header {
  background: var(--color-surface);
  padding: var(--spacing-3xl) 0;
  text-align: center;
}

.page-title {
  font-size: var(--font-size-3xl);
  margin-bottom: var(--spacing-md);
}

.page-subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
}

.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--spacing-2xl);
  padding: var(--spacing-2xl) 0;
}

.sidebar {
  position: sticky;
  top: 80px;
  height: fit-content;
}

.sidebar-section {
  margin-bottom: var(--spacing-xl);
}

.sidebar-title {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-muted);
  margin-bottom: var(--spacing-md);
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.sidebar-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
}

.sidebar-link:hover,
.sidebar-link.active {
  background: var(--color-surface);
  color: var(--color-text-primary);
}

.sidebar-link.active {
  background: var(--color-primary);
  color: var(--color-white);
}

.sidebar-link svg {
  opacity: 0.5;
}

.course-count {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  background: var(--color-surface);
  padding: 2px 8px;
  border-radius: var(--radius-full);
}

.course-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xl);
}

.course-list .course-card {
  display: grid;
  grid-template-columns: 280px 1fr;
}

.course-list .course-card-image {
  aspect-ratio: 16/10;
}

.course-list .course-card-content {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: var(--spacing-lg);
}

.category-row {
  margin-bottom: var(--spacing-2xl);
}

/* ===== Projects Page ===== */
.projects-filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xl) 0;
  border-bottom: 1px solid var(--color-border);
  flex-wrap: wrap;
  gap: var(--spacing-md);
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  flex-wrap: wrap;
}

.filter-btn {
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  background: var(--color-surface);
  transition: all var(--transition-fast);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--color-foreground);
  color: var(--color-white);
}

.sort-select {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
