  text-align: center;
}

.countdown-separator {
  animation: blink 1s infinite;
}

@keyframes blink {
  0%, 50% { opacity: 1; }
  51%, 100% { opacity: 0; }
}

.promo-close {
  position: absolute;
  right: var(--spacing-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-white);
  opacity: 0.8;
  padding: var(--spacing-xs);
}

.promo-close:hover {
